import { useEffect, useMemo, useRef, useState } from "react";
import {
  Alert,
  Card,
  Chip,
} from "@heroui/react";
import { companyFixture, currentUserFixture, type UserRole } from "./fixtures";

type DemoState =
  | "default"
  | "drawer-open"
  | "invalid-seat-count"
  | "unauthorized"
  | "loading"
  | "success"
  | "failure";

type PlanId = "starter" | "business" | "enterprise";

type ContractDraft = {
  plan: PlanId;
  seats: number;
};

type BannerState = {
  status: "accent" | "success" | "warning" | "danger";
  title: string;
  description: string;
} | null;

type DemoPreset = {
  role: UserRole;
  contract: ContractDraft;
  draft: ContractDraft;
  isDrawerOpen: boolean;
  banner: BannerState;
  isSaving: boolean;
};

const demoStates: DemoState[] = [
  "default",
  "drawer-open",
  "invalid-seat-count",
  "unauthorized",
  "loading",
  "success",
  "failure",
];

const plans: Array<{ id: PlanId; label: string }> = [
  { id: "starter", label: "Starter" },
  { id: "business", label: "Business" },
  { id: "enterprise", label: "Enterprise" },
];

const defaultDraft: ContractDraft = { plan: "business", seats: companyFixture.seats };
const successDraft: ContractDraft = { plan: "enterprise", seats: 60 };
const failureDraft: ContractDraft = { plan: "enterprise", seats: 48 };

function formatDateRange(start: string, end: string) {
  const formatter = new Intl.DateTimeFormat("ja-JP", {
    year: "numeric",
    month: "long",
    day: "numeric",
  });

  return `${formatter.format(new Date(start))}から${formatter.format(new Date(end))}`;
}

function getStateFromQuery() {
  if (typeof window === "undefined") {
    return "default" satisfies DemoState;
  }

  const value = new URLSearchParams(window.location.search).get("state");
  return demoStates.includes(value as DemoState) ? (value as DemoState) : "default";
}

function getDemoPreset(state: DemoState): DemoPreset {
  switch (state) {
    case "drawer-open":
      return {
        role: currentUserFixture.role,
        contract: defaultDraft,
        draft: defaultDraft,
        isDrawerOpen: true,
        banner: null,
        isSaving: false,
      };
    case "invalid-seat-count":
      return {
        role: currentUserFixture.role,
        contract: defaultDraft,
        draft: { plan: "business" as const, seats: 41 },
        isDrawerOpen: true,
        banner: null,
        isSaving: false,
      };
    case "unauthorized":
      return {
        role: "viewer" satisfies UserRole,
        contract: defaultDraft,
        draft: defaultDraft,
        isDrawerOpen: false,
        banner: {
          status: "warning" as const,
          title: "CS Viewerは契約を変更できません",
          description: "閲覧のみ可能です。契約変更が必要な場合はCS Managerへ依頼してください。",
        },
        isSaving: false,
      };
    case "loading":
      return {
        role: currentUserFixture.role,
        contract: defaultDraft,
        draft: failureDraft,
        isDrawerOpen: true,
        banner: {
          status: "accent" as const,
          title: "契約変更を保存しています",
          description: "保存完了まで、内容の変更と二重送信を停止しています。",
        },
        isSaving: true,
      };
    case "success":
      return {
        role: currentUserFixture.role,
        contract: successDraft,
        draft: successDraft,
        isDrawerOpen: false,
        banner: {
          status: "success" as const,
          title: "契約内容を更新しました",
          description: "プランをEnterprise、契約席数を60席へ反映済みです。",
        },
        isSaving: false,
      };
    case "failure":
      return {
        role: currentUserFixture.role,
        contract: defaultDraft,
        draft: failureDraft,
        isDrawerOpen: true,
        banner: {
          status: "danger" as const,
          title: "契約内容を更新できませんでした",
          description: "入力内容は保持しています。内容を確認して再試行してください。",
        },
        isSaving: false,
      };
    case "default":
    default:
      return {
        role: currentUserFixture.role,
        contract: defaultDraft,
        draft: defaultDraft,
        isDrawerOpen: false,
        banner: null,
        isSaving: false,
      };
  }
}

export function App() {
  const [demoState, setDemoState] = useState<DemoState>(() => getStateFromQuery());
  const initialPreset = useMemo(() => getDemoPreset(demoState), [demoState]);
  const [role, setRole] = useState<UserRole>(initialPreset.role as UserRole);
  const [contract, setContract] = useState<ContractDraft>(initialPreset.contract);
  const [draft, setDraft] = useState<ContractDraft>(initialPreset.draft);
  const [selectedPlan, setSelectedPlan] = useState<PlanId>(initialPreset.draft.plan);
  const [seatInput, setSeatInput] = useState(String(initialPreset.draft.seats));
  const [banner, setBanner] = useState<BannerState>(initialPreset.banner);
  const [isSaving, setIsSaving] = useState(initialPreset.isSaving);
  const [isConfirmOpen, setIsConfirmOpen] = useState(false);
  const saveTimerRef = useRef<number | null>(null);

  useEffect(() => {
    const preset = getDemoPreset(demoState);
    setRole(preset.role);
    setContract(preset.contract);
    setDraft(preset.draft);
    setSelectedPlan(preset.draft.plan);
    setSeatInput(String(preset.draft.seats));
    setBanner(preset.banner);
    setIsSaving(preset.isSaving);
    setIsConfirmOpen(false);

    if (typeof window !== "undefined") {
      const url = new URL(window.location.href);
      url.searchParams.set("state", demoState);
      window.history.replaceState({}, "", url);
    }
  }, [demoState]);

  useEffect(() => {
    return () => {
      if (saveTimerRef.current !== null) {
        window.clearTimeout(saveTimerRef.current);
      }
    };
  }, []);

  const usedSeats = companyFixture.usedSeats;
  const remainingSeats = contract.seats - usedSeats;
  const parsedSeatCount = Number(seatInput);
  const isSeatCountInvalid =
    Number.isNaN(parsedSeatCount) || !Number.isInteger(parsedSeatCount) || parsedSeatCount < usedSeats;
  const canEdit = role === "manager";
  const pendingDraft: ContractDraft = {
    plan: selectedPlan,
    seats: Number.isNaN(parsedSeatCount) ? usedSeats : parsedSeatCount,
  };
  const planLabel = plans.find((plan) => plan.id === contract.plan)?.label ?? contract.plan;
  const pendingPlanLabel = plans.find((plan) => plan.id === pendingDraft.plan)?.label ?? pendingDraft.plan;
  const hasUnsavedChanges =
    pendingDraft.plan !== contract.plan || pendingDraft.seats !== contract.seats;

  const applyStatePreset = (nextState: DemoState) => {
    if (saveTimerRef.current !== null) {
      window.clearTimeout(saveTimerRef.current);
      saveTimerRef.current = null;
    }
    setDemoState(nextState);
  };

  const openEditor = () => {
    if (!canEdit || isSaving) {
      return;
    }

    setDemoState("drawer-open");
    setDraft(contract);
    setSelectedPlan(contract.plan);
    setSeatInput(String(contract.seats));
    setBanner(null);
  };

  const closeEditor = () => {
    if (isSaving) {
      return;
    }

    setIsConfirmOpen(false);
    if (demoState === "drawer-open" || demoState === "invalid-seat-count" || demoState === "failure") {
      setDemoState("default");
    }
  };

  const handleSeatInputChange = (value: string) => {
    setSeatInput(value);
    if (Number(value) < usedSeats) {
      setDemoState("invalid-seat-count");
      return;
    }

    if (demoState === "invalid-seat-count") {
      setDemoState("drawer-open");
    }
  };

